mapper.select:
SELECT si.`id` AS `id`, si.`shop_id` AS `shopId`, si.`item_name` AS `itemName`, si.`color` AS `color`, si.`size` AS `size`, si.`price` AS `price`, si.`style` AS `style`, si.`main_category` AS `mainCategory`, si.`sub_category` AS `subCategory`, si.`detail_category` AS `detailCategory`, si.`created_at` AS `createdAt`, si.`updated_at` AS `updateAt`, si.`deleted_at` AS `deletedAt`, (SELECT img.`image_path` FROM `cors`.`shop_item_images` img WHERE img.`product_id` = si.`id` LIMIT 1) AS `imagePath` FROM `cors`.`shop_items` si WHERE si.`shop_id` = #{shopId}
AND ( si.`main_category` = #{categoryName} OR si.`sub_category` = #{categoryName} OR si.`detail_category` = #{categoryName} )
ORDER BY si.`updated_at` DESC

SELECT COUNT(0)
FROM `cors`.`like_items`
WHERE `user_email` = #{userEmail}
  AND `shop_id` = #{shopId}
  AND `item_id` = #{itemId}

SELECT si.`id` AS `id`, si.`item_name` AS `itemName`, si.`shop_id` AS `shopId`, si.`color` AS `color`, si.`size` AS `size`, si.`price` AS `price`, si.`style` AS `style`, si.`main_category` AS `mainCategory`, si.`sub_category` AS `subCategory`, si.`detail_category` AS `detailCategory`, si.`created_at` AS `createdAt`, si.`updated_at` AS `updateAt`, si.`deleted_at` AS `deletedAt`, info.`shop_time` AS `shopTime`, (SELECT img.`image_path` FROM `cors`.`shop_item_images` img WHERE img.`product_id` = si.`id` LIMIT 1) AS `imagePath` FROM `cors`.`shop_items` si /* [중요] 주소 비교를 위해 매장 정보와 JOIN */ JOIN `cors`.`shop_info` info ON si.`shop_id` = info.`shop_id`
ORDER BY /* 1순위: 거리 점수 */ (CASE WHEN info.`shop_address` LIKE CONCAT(#{address}, '%') THEN 2 WHEN info.`shop_address` LIKE CONCAT(#{region}, '%') THEN 1 ELSE 0 END) DESC, /* 2순위: 좋아요 많은 순 */ (SELECT COUNT(*) FROM `cors`.`like_items` WHERE `item_id` = si.`id`) DESC, si.`updated_at` DESC
ORDER BY
/* 2순위: 가격 낮은 순 */ si.`price` ASC
ORDER BY si.`updated_at` DESC
LIMIT #{page.rowCount} OFFSET #{page.dbOffset}

SELECT si.`id` AS `id`, si.`shop_id` AS `shopId`, si.`item_name` AS `itemName`, si.`color` AS `color`, si.`size` AS `size`, si.`price` AS `price`, si.`style` AS `style`, si.`main_category` AS `mainCategory`, si.`sub_category` AS `subCategory`, si.`detail_category` AS `detailCategory`, si.`created_at` AS `createdAt`, si.`updated_at` AS `updateAt`, si.`deleted_at` AS `deletedAt`, (SELECT img.`image_path` FROM `cors`.`shop_item_images` img WHERE img.`product_id` = si.`id` LIMIT 1) AS `imagePath`, (SELECT IFNULL(AVG(ir.`rating`), 0) FROM `cors`.`item_reviews` ir WHERE ir.`item_id` = si.`id`) AS `rating`, (SELECT COUNT(0) FROM `cors`.`item_reviews` ir WHERE ir.`item_id` = si.`id`) AS `reviewCount` FROM `cors`.`shop_items` si WHERE si.`style` IN
#{category}
ORDER BY `rating` DESC, `reviewCount` DESC, si.`updated_at` DESC LIMIT 4

SELECT si.`id` AS `id`, si.`shop_id` AS `shopId`, si.`item_name` AS `itemName`, si.`color` AS `color`, si.`size` AS `size`, si.`price` AS `price`, si.`style` AS `style`, si.`main_category` AS `mainCategory`, si.`sub_category` AS `subCategory`, si.`detail_category` AS `detailCategory`, si.`created_at` AS `createdAt`, si.`updated_at` AS `updateAt`, si.`deleted_at` AS `deletedAt`, (SELECT img.`image_path` FROM `cors`.`shop_item_images` img WHERE img.`product_id` = si.`id` LIMIT 1) AS `imagePath`, (SELECT IFNULL(AVG(ir.`rating`), 0) FROM `cors`.`item_reviews` ir WHERE ir.`item_id` = si.`id`) AS `rating`, (SELECT COUNT(0) FROM `cors`.`item_reviews` ir WHERE ir.`item_id` = si.`id`) AS `reviewCount` FROM `cors`.`shop_items` si WHERE si.`style` IN
#{category}
ORDER BY si.`updated_at` DESC
